def choose_move(observation):
    # Defensive retrieval of fields
    grid = observation.get('grid', [])
    pos = observation.get('position', (0, 0))
    last_action = observation.get('last_action', None)
    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territory_mask = observation.get('territory_mask', [])

    x, y = pos

    # Directions: N, S, E, W, stay
    directions = {
        'stay': (0, 0),
        'north': (-1, 0),
        'south': (1, 0),
        'east': (0, 1),
        'west': (0, -1)
    }

    def is_safe(nx, ny):
        # Check bounds
        if not grid:
            # assume infinite or unknown grid: be conservative
            return True
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
            # Avoid obstacles if any
            cell = grid[nx][ny]
            return cell != 'obstacle'
        return False

    # Search for nearby resources
    for dx, dy in directions.values():
        nx, ny = x + dx, y + dy
        if is_safe(nx, ny):
            if resources:
                # Prefer moving towards resources if adjacent
                if (nx, ny) in resources:
                    return [dx, dy]

    # Pursue opponents if adjacent
    for opp in opponents:
        opp_x, opp_y = opp.get('position', (None, None))
        if opp_x is None or opp_y is None:
            continue
        dist_x = opp_x - x
        dist_y = opp_y - y
        if abs(dist_x) + abs(dist_y) == 1:
            return [dist_x, dist_y]

    # Territory control: move towards unclaimed territory
    if territory_mask:
        for dx, dy in directions.values():
            nx, ny = x + dx, y + dy
            if is_safe(nx, ny):
                try:
                    if not territory_mask[nx][ny]:
                        return [dx, dy]
                except IndexError:
                    continue

    # Default: stay in place
    return [0, 0]

